mapper.select:
SELECT u.id, u.userName, u.account, u.phone, u.email, u.`describe`, u.balance, u.avatarPath, u.level,
       u.vipCreateTime, u.vipDuration, u.createTime, u.uploadTime, u.uploadBackground, u.uploadGoods, u.updateAvatar, u.`delete`
FROM user u

    AND u.id = #{entity.id}
    AND u.userName LIKE CONCAT('%', #{entity.userName}, '%')
    AND u.account LIKE CONCAT('%', #{entity.account}, '%')
    AND u.phone LIKE CONCAT('%', #{entity.phone}, '%')
    AND u.email LIKE CONCAT('%', #{entity.email}, '%')
    AND u.`describe` LIKE CONCAT('%', #{entity.describe}, '%')
    AND u.avatarPath LIKE CONCAT('%', #{entity.avatarPath}, '%')
    AND u.createTime >= #{entity.createTimeStart}
    AND u.createTime <= #{entity.createTimeEnd}
    AND u.level = #{entity.level}
    AND u.`delete` = #{entity.delete}

SELECT a.id, a.userId, a.addressId, a.country, a.province, a.city, a.county, a.detail, a.createTime, a.`delete`,
       u.userName
FROM address a
LEFT JOIN user u ON a.userId = u.id

    AND a.id = #{entity.id}
    AND a.userId = #{entity.userId}
    AND u.userName LIKE CONCAT('%', #{entity.userName}, '%')
    AND a.createTime >= #{entity.createTimeStart}
    AND a.createTime <= #{entity.createTimeEnd}
    AND a.`delete` = #{entity.delete}

SELECT c.id, c.userId, c.goodId, c.quantity, c.createTime,
       u.userName, g.goodsName, g.goodsPrice, g.imagePath, g.goodsStock, g.launch
FROM cart c
LEFT JOIN user u ON c.userId = u.id
LEFT JOIN goods g ON c.goodId = g.id

    AND c.id = #{entity.id}
    AND c.userId = #{entity.userId}
    AND u.userName LIKE CONCAT('%', #{entity.userName}, '%')
    AND g.goodsName LIKE CONCAT('%', #{entity.goodsName}, '%')
    AND g.goodsStock = #{entity.goodsStock}
    AND c.quantity = #{entity.quantity}
    AND g.launch = #{entity.launch}
    AND c.createTime >= #{entity.createTimeStart}
    AND c.createTime <= #{entity.createTimeEnd}

SELECT g.id, u.userName, g.goodsName, CONCAT(ad.country, ad.province, ad.city, ad.county, ad.detail) AS address, g.goodsPrice, g.goodsStock, g.imagePath, g.launch, g.preId, g.createTime, g.`delete`, g.describe
FROM goods g
LEFT JOIN user u ON g.userId = u.id
LEFT JOIN address ad ON g.addressId = ad.id

    AND g.id = #{entity.id}
    AND g.preId = #{entity.preId}
    AND u.userName LIKE CONCAT('%', #{entity.userName}, '%')
    AND g.goodsName LIKE CONCAT('%', #{entity.goodsName}, '%')
    AND g.goodsPrice >= #{entity.priceStart}
    AND g.goodsPrice <= #{entity.priceEnd}
    AND CONCAT(ad.country, ad.province, ad.city, ad.county, ad.detail) LIKE CONCAT('%', #{entity.address}, '%')
    AND g.describe LIKE CONCAT('%', #{entity.describe}, '%')
    AND g.createTime >= #{entity.createTimeStart}
    AND g.createTime <= #{entity.createTimeEnd}
    AND g.launch = #{entity.launch}
    AND g.`delete` = #{entity.delete}

SELECT t.id, t.orderId, t.userId, t.goodId, t.quantity, t.originAddress, t.currentAddress, t.targetAddress,
       t.createTime, t.payTime, t.cancelTime, t.finishTime, t.`delete`,
       u.userName, m.userName AS merchantName, g.goodsName, g.goodsPrice,
       (g.goodsPrice * t.quantity) AS totalPrice
FROM trade t
LEFT JOIN user u ON t.userId = u.id
LEFT JOIN goods g ON t.goodId = g.id
LEFT JOIN user m ON g.userId = m.id

    t.`delete` = 0
    AND t.id = #{entity.id}
    AND t.userId = #{entity.userId}
    AND u.userName LIKE CONCAT('%', #{entity.userName}, '%')
    AND m.userName LIKE CONCAT('%', #{entity.merchantName}, '%')
    AND g.goodsName LIKE CONCAT('%', #{entity.goodsName}, '%')
    AND t.originAddress LIKE CONCAT('%', #{entity.originAddress}, '%')
    AND t.currentAddress LIKE CONCAT('%', #{entity.currentAddress}, '%')
    AND t.targetAddress LIKE CONCAT('%', #{entity.targetAddress}, '%')
    AND t.createTime >= #{entity.createTimeStart}
    AND t.createTime <= #{entity.createTimeEnd}
    AND t.payTime >= #{entity.payTimeStart}
    AND t.payTime <= #{entity.payTimeEnd}
    AND t.cancelTime >= #{entity.cancelTimeStart}
    AND t.cancelTime <= #{entity.cancelTimeEnd}
    AND t.finishTime >= #{entity.finishTimeStart}
    AND t.finishTime <= #{entity.finishTimeEnd}
    AND t.`delete` = #{entity.delete}

SELECT level, maxAddressQuantity, monthlyUpdateGoods, monthlyUpdateAvatar, monthlyUpdateBackground,
       maxCartQuantity, maxGoodsQuantity, maxAiQuantity, price, vipDuration, createTime
FROM vipconfig

    AND u.level = #{entity.level}
    AND maxAddressQuantity = #{entity.maxAddressQuantity}
    AND monthlyUpdateGoods = #{entity.monthlyUpdateGoods}
    AND monthlyUpdateAvatar = #{entity.monthlyUpdateAvatar}
    AND monthlyUpdateBackground = #{entity.monthlyUpdateBackground}
    AND maxCartQuantity = #{entity.maxCartQuantity}
    AND maxGoodsQuantity = #{entity.maxGoodsQuantity}
    AND maxAiQuantity = #{entity.maxAiQuantity}
    AND price = #{entity.price}

ORDER BY level ASC

SELECT vt.id, vt.userId, vt.level, vt.money, vt.num, vt.createTime,
       u.userName
FROM viptrade vt
LEFT JOIN user u ON vt.userId = u.id

    AND vt.id = #{entity.id}
    AND vt.userId = #{entity.userId}
    AND u.userName LIKE CONCAT('%', #{entity.userName}, '%')
    AND vt.level = #{entity.level}
    AND vt.money >= #{entity.moneyStart}
    AND vt.money <= #{entity.moneyEnd}
    AND vt.createTime >= #{entity.createTimeStart}
    AND vt.createTime <= #{entity.createTimeEnd}
    AND vt.`delete` = #{entity.delete}

SELECT a.id, a.userId, a.goodsId, a.category, a.kind, a.name, a.price, a.simpleDescription, a.features, a.createTime, a.`delete`,
       u.userName
FROM ai a
LEFT JOIN user u ON a.userId = u.id

    AND a.id = #{entity.id}
    AND a.userId = #{entity.userId}
    AND u.userName LIKE CONCAT('%', #{entity.userName}, '%')
    AND a.goodsId = #{entity.goodsId}
    AND a.category LIKE CONCAT('%', #{entity.category}, '%')
    AND a.kind LIKE CONCAT('%', #{entity.kind}, '%')
    AND a.name LIKE CONCAT('%', #{entity.name}, '%')
    AND a.price >= #{entity.priceStart}
    AND a.price <= #{entity.priceEnd}
    AND a.simpleDescription LIKE CONCAT('%', #{entity.simpleDescription}, '%')
    AND a.features LIKE CONCAT('%', #{entity.features}, '%')
    AND a.createTime >= #{entity.createTimeStart}
    AND a.createTime <= #{entity.createTimeEnd}
    AND a.`delete` = #{entity.delete}
